+        ChatMessage::user("q2"),
+        ChatMessage::assistant_blocks(vec![
+            AssistantContentBlock::Reasoning { text: "r2".into() },
+            AssistantContentBlock::ToolCall(AssistantToolCall {
+                id: "call-1".to_string(),
+                name: "lookup".to_string(),
+                arguments: "{}".to_string(),
+            }),
+        ]),
+        ChatMessage::tool_response("value", "call-1"),
+    ];
